369:   function render(frame) {
370:     currentZoom = frame.camera.z;
371:     resize();
372:     const centerX = (frame.camera.x - .5) * WORLD * aspect;
373:     const centerZ = (frame.camera.y - .5) * WORLD;
374:     camera.position.set(centerX, 190, centerZ + 92);
375:     camera.lookAt(centerX, 0, centerZ);
376:     camera.rotation.z = 0;
377:     camera.left = -HALF_VIEW * aspect / currentZoom; camera.right = HALF_VIEW * aspect / currentZoom;
378:     camera.top = HALF_VIEW / currentZoom; camera.bottom = -HALF_VIEW / currentZoom; camera.updateProjectionMatrix();
379: 
380:     const live = new Set();
381:     updateFog(frame);
382:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
383:       live.add(entity.id);
384:       let obj = entities.get(entity.id);
385:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
386:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
387:         obj = buildEntity(entity, frame.faction); entities.set(entity.id, obj); entityRoot.add(obj);
388:       }
389:       const scale = entity.size ? Math.max(.35, entity.size / 70) : Math.max(.85, entity.radius / 7);
390:       position(obj, entity.x, entity.y);
391:       obj.scale.setScalar(scale);
392:       const moving = entity.move && Math.hypot((entity.move.x - entity.x) * aspect, entity.move.y - entity.y) > .003;
393:       const moveAngle = moving ? Math.atan2(-(entity.move.x - entity.x) * aspect, -(entity.move.y - entity.y)) : null;
394:       const aimAngle = entity.target ? Math.atan2(-(entity.target.x - entity.x) * aspect, -(entity.target.y - entity.y)) : null;
395:       const turret = obj.userData.model.getObjectByName('turret');
396:       // Track actual displacement so AI-driven units and vehicles face their travel direction too.
397:       const previous = obj.userData.lastPosition;
398:       if (previous) {
399:         const dx = (entity.x - previous.x) * aspect, dy = entity.y - previous.y;
400:         if (dx * dx + dy * dy > 1e-8) obj.userData.heading = Math.atan2(-dx, -dy);
401:       }
402:       obj.userData.lastPosition = { x: entity.x, y: entity.y };
403:       // Models are built facing local -Z. Movement takes precedence; stationary combat units face targets.
404:       obj.rotation.y = entity.size ? 0 : (obj.userData.heading ?? moveAngle ?? (aimAngle !== null && !turret ? aimAngle : 0));
405:       const soldiers = obj.userData.model.userData.soldiers;
406:       if (soldiers) {
407:         const stride = moving ? Math.min(1, .45 + (entity.speed || 20) / 55) : 0;
408:         for (const gait of soldiers) {
409:           const swing = Math.sin(frame.time * 10 + gait.phase) * .52 * stride;
410:           for (const leg of gait.legs) leg.mesh.rotation.x = leg.base + swing;
411:           for (const arm of gait.arms) arm.mesh.rotation.x = arm.base - swing * .42;
412:           gait.soldier.position.y = gait.baseY + Math.abs(Math.sin(frame.time * 10 + gait.phase)) * .055 * stride;
413:         }
414:       }
415:       const fogIndex = Math.max(0, Math.min(127, Math.floor(entity.y * 128))) * 128 + Math.max(0, Math.min(127, Math.floor(entity.x * 128)));
416:       obj.visible = entity.hp > 0 && (entity.team === 'blue' || visibleCells[fogIndex] === 1);
417:       obj.userData.selection.visible = entity === frame.selected;
418:       obj.userData.selection.scale.setScalar(entity.size ? 1 : .6);
419:       obj.userData.selection.material.opacity = entity.team === 'blue' ? .9 : .65;
420:       obj.userData.model.rotation.y = 0;
421:       if (turret) turret.rotation.y = aimAngle === null ? 0 : aimAngle - obj.rotation.y;
422:       obj.userData.health.visible = entity.hp < entity.max;
423:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
424:       obj.userData.healthFill.scale.x = ratio;
425:       obj.userData.healthFill.position.x = -(obj.userData.health.userData.width * (1 - ratio)) / 2;
426:       const hopper = obj.getObjectByName('ore hopper');
427:       if (hopper) hopper.material = entity.carry > 0 ? mat('#b6944d') : mat('#756a49');
428:       const vehicle = obj.userData.model.getObjectByName('vehicle');
429:       if (vehicle) vehicle.position.y = entity.kind === 'collector' && entity.harvesting ? Math.sin(frame.time * 2.5) * .08 : 0;
430:     }
431:     for (const [id, obj] of entities) if (!live.has(id)) { entityRoot.remove(obj); disposeTree(obj); entities.delete(id); }
432:     syncResources(frame);
433:     syncEffects(frame);
434:     let ghost = scene.getObjectByName('placement-preview');
435:     if (frame.placement) {
436:       if (!ghost) {
437:         ghost = new THREE.Mesh(new THREE.BoxGeometry(8, 4, 8), new THREE.MeshBasicMaterial({ color: '#c8f05b', wireframe: true, transparent: true, opacity: .8 }));
438:         ghost.name = 'placement-preview'; scene.add(ghost);
439:       }
440:       const pointer = frame.pointer || { x: .5, y: .5 };
441:       position(ghost, pointer.x, pointer.y, 2); ghost.visible = true;
442:     } else if (ghost) ghost.visible = false;
443:     renderer.render(scene, camera);
444:   }
