import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
try {
 const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
 const errors=[];
 page.on('pageerror', e => errors.push(e.message));
 page.on('console', m => { if (m.type()==='error') errors.push(m.text()); });
 page.on('requestfailed', r => errors.push(`FAILED ${r.url()}`));
 page.on('response', r => {if(r.status()>=400) errors.push(`${r.status()} ${r.url()}`)});
 await page.goto('http://localhost:3000', { waitUntil: 'load' });
 await page.locator('#start-btn').click();
 const canvas=page.locator('#battlefield');
 const box=await canvas.boundingBox();
 await page.mouse.move(box.x+box.width/2, box.y+box.height/2);
 await page.mouse.wheel(0,-500);
 await page.waitForTimeout(10000);
 mkdirSync('screenshots', {recursive:true});
 await page.screenshot({path:'screenshots/frontline-check-04.jpeg',type:'jpeg',quality:92});
 console.log(JSON.stringify({title: await page.title(), viewport: page.viewportSize(), canvas: box, errors}));
} finally { await browser.close(); }
