514:   function syncEffects(frame) {
515:     const key = `${frame.shots.length}:${frame.particles.length}:${Math.floor(frame.time * 10)}`;
516:     if (transientKey === key) return;
517:     transientKey = key;
518:     while (transientRoot.children.length) {
519:       const child = transientRoot.children[0]; transientRoot.remove(child); disposeTree(child);
520:     }
521:     const up = new THREE.Vector3(0, 1, 0);
522:     const addTracer = (from, to, radius, color) => {
523:       const delta = to.clone().sub(from), length = delta.length();
524:       if (length < .025) return;
525:       const tracer = new THREE.Mesh(new THREE.CylinderGeometry(radius * .72, radius, length, 6), basic(color));
526:       tracer.position.copy(from).add(to).multiplyScalar(.5);
527:       tracer.quaternion.setFromUnitVectors(up, delta.normalize());
528:       transientRoot.add(tracer);
529:     };
530:     for (const shot of frame.shots) {
531:       if (!shot.target) continue;
532:       const t = Math.max(0, Math.min(1, 1 - shot.life / shot.max));
533:       const weapon = shot.weapon || (shot.sourceKind === 'tank' ? 'cannon' : shot.sourceKind === 'infantry' ? 'rifle' : 'machinegun');
534:       const height = weapon === 'missile' ? 5.2 : weapon === 'cannon' ? 2.65 : weapon === 'flak' ? 3.15 : weapon === 'autocannon' ? 2.45 : weapon === 'rifle' ? 1.45 : 2.05;
535:       const a = new THREE.Vector3((shot.x - .5) * WORLD * aspect, height, (shot.y - .5) * WORLD);
536:       const progress = t;
537:       const arc = weapon === 'cannon' ? Math.sin(Math.PI * progress) * 3.8 : weapon === 'flak' ? Math.sin(Math.PI * progress) * 2.2 : 0;
538:       const b = new THREE.Vector3((shot.x + (shot.target.x - shot.x) * progress - .5) * WORLD * aspect, height + arc, (shot.y + (shot.target.y - shot.y) * progress - .5) * WORLD);
539:       const direction = b.clone().sub(a).normalize();
540:       const color = shot.color || '#f4d781';
541:       if (weapon === 'cannon') {
542:         const trailStart = b.clone().lerp(a, .22);
543:         addTracer(trailStart, b, .11, '#ffd77a');
544:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.34, 10, 8), mat('#3c3b32', .38, .62));
545:         shell.position.copy(b); shell.scale.set(.9, .8, 1.25); transientRoot.add(shell);
546:         const glint = new THREE.Mesh(new THREE.SphereGeometry(.16, 8, 6), basic('#ffb34e'));
547:         glint.position.copy(b); transientRoot.add(glint);
548:       } else if (weapon === 'missile') {
549:         const trailStart = b.clone().lerp(a, .16);
550:         addTracer(trailStart, b, .16, '#ef9d4c');
551:         const missile = new THREE.Group();
552:         const body = new THREE.Mesh(new THREE.CylinderGeometry(.14, .2, .95, 8), mat('#55564a', .42, .55));
553:         body.rotation.x = Math.PI / 2; missile.add(body);
554:         const nose = new THREE.Mesh(new THREE.ConeGeometry(.15, .34, 8), mat('#c4b58b', .48, .35));
555:         nose.rotation.x = -Math.PI / 2; nose.position.z = -.62; missile.add(nose);
556:         for (let i = 0; i < 4; i++) {
557:           const fin = new THREE.Mesh(new THREE.BoxGeometry(.34, .07, .27), mat('#383b34', .55, .4));
558:           fin.position.set(Math.cos(i * Math.PI / 2) * .19, Math.sin(i * Math.PI / 2) * .19, .31); missile.add(fin);
559:         }
560:         missile.position.copy(b); missile.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), direction);
561:         transientRoot.add(missile);
562:         const flame = new THREE.Mesh(new THREE.ConeGeometry(.19, .62, 8), basic('#ff7838', .9));
563:         flame.position.copy(b).addScaledVector(direction, -.68);
564:         flame.quaternion.setFromUnitVectors(up, direction.clone().negate()); transientRoot.add(flame);
565:       } else if (weapon === 'flak') {
566:         addTracer(b.clone().lerp(a, .28), b, .095, '#ffb75d');
567:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.23, 9, 7), mat('#51483a', .46, .5));
568:         shell.position.copy(b); transientRoot.add(shell);
569:         const glow = new THREE.Mesh(new THREE.SphereGeometry(.34, 8, 6), basic('#ff9e49', .35));
570:         glow.position.copy(b); transientRoot.add(glow);
571:       } else {
572:         const radius = weapon === 'autocannon' ? .062 : weapon === 'rifle' ? .032 : .048;
573:         const tracerColor = weapon === 'rifle' ? '#f5e4ad' : weapon === 'autocannon' ? '#ffb94e' : color;
574:         addTracer(a, b, radius, tracerColor);
575:         const tip = new THREE.Mesh(new THREE.SphereGeometry(weapon === 'autocannon' ? .13 : .085, 7, 5), basic(tracerColor));
576:         tip.position.copy(b); transientRoot.add(tip);
577:       }
