407:   function render(frame) {
408:     currentZoom = frame.camera.z;
409:     resize();
410:     const centerX = (frame.camera.x - .5) * WORLD * aspect;
411:     const centerZ = (frame.camera.y - .5) * WORLD;
412:     camera.position.set(centerX, 190, centerZ + 92);
413:     camera.lookAt(centerX, 0, centerZ);
414:     camera.rotation.z = 0;
415:     camera.left = -HALF_VIEW * aspect / currentZoom; camera.right = HALF_VIEW * aspect / currentZoom;
416:     camera.top = HALF_VIEW / currentZoom; camera.bottom = -HALF_VIEW / currentZoom; camera.updateProjectionMatrix();
417: 
418:     const live = new Set();
419:     updateFog(frame);
420:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
421:       live.add(entity.id);
422:       let obj = entities.get(entity.id);
423:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
424:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
425:         obj = buildEntity(entity, frame.faction); entities.set(entity.id, obj); entityRoot.add(obj);
426:       }
427:       const scale = entity.size ? Math.max(.35, entity.size / 70) : Math.max(.85, entity.radius / 7);
428:       position(obj, entity.x, entity.y);
429:       obj.scale.setScalar(scale);
430:       const moving = entity.move && Math.hypot((entity.move.x - entity.x) * aspect, entity.move.y - entity.y) > .003;
431:       const moveAngle = moving ? Math.atan2(-(entity.move.x - entity.x) * aspect, -(entity.move.y - entity.y)) : null;
432:       const aimAngle = entity.target ? Math.atan2(-(entity.target.x - entity.x) * aspect, -(entity.target.y - entity.y)) : null;
433:       const turret = obj.userData.model.getObjectByName('turret');
434:       // Track actual displacement so AI-driven units and vehicles face their travel direction too.
435:       const previous = obj.userData.lastPosition;
436:       if (previous) {
437:         const dx = (entity.x - previous.x) * aspect, dy = entity.y - previous.y;
438:         if (dx * dx + dy * dy > 1e-8) obj.userData.heading = Math.atan2(-dx, -dy);
439:       }
440:       obj.userData.lastPosition = { x: entity.x, y: entity.y };
441:       // Models are built facing local -Z. Movement takes precedence; stationary combat units face targets.
442:       obj.rotation.y = entity.size ? 0 : (obj.userData.heading ?? moveAngle ?? (aimAngle !== null && !turret ? aimAngle : 0));
443:       const soldiers = obj.userData.model.userData.soldiers;
444:       if (soldiers) {
445:         const stride = moving ? Math.min(1, .45 + (entity.speed || 20) / 55) : 0;
446:         for (const gait of soldiers) {
447:           const swing = Math.sin(frame.time * 10 + gait.phase) * .52 * stride;
448:           for (const leg of gait.legs) leg.mesh.rotation.x = leg.base + swing;
449:           for (const arm of gait.arms) arm.mesh.rotation.x = arm.base - swing * .42;
450:           gait.soldier.position.y = gait.baseY + Math.abs(Math.sin(frame.time * 10 + gait.phase)) * .055 * stride;
451:         }
452:       }
453:       const fogIndex = Math.max(0, Math.min(127, Math.floor(entity.y * 128))) * 128 + Math.max(0, Math.min(127, Math.floor(entity.x * 128)));
454:       obj.visible = entity.hp > 0 && (entity.team === 'blue' || visibleCells[fogIndex] === 1);
455:       obj.userData.selection.visible = entity === frame.selected;
456:       obj.userData.selection.scale.setScalar(entity.size ? 1 : .6);
457:       obj.userData.selection.material.opacity = entity.team === 'blue' ? .9 : .65;
458:       obj.userData.model.rotation.y = 0;
459:       if (turret) turret.rotation.y = aimAngle === null ? 0 : aimAngle - obj.rotation.y;
460:       obj.userData.health.visible = entity.hp < entity.max;
461:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
462:       obj.userData.healthFill.scale.x = ratio;
463:       obj.userData.healthFill.position.x = -(obj.userData.health.userData.width * (1 - ratio)) / 2;
464:       const hopper = obj.getObjectByName('ore hopper');
465:       if (hopper) hopper.material = entity.carry > 0 ? mat('#b6944d') : mat('#756a49');
466:       const vehicle = obj.userData.model.getObjectByName('vehicle');
467:       if (vehicle) vehicle.position.y = entity.kind === 'collector' && entity.harvesting ? Math.sin(frame.time * 2.5) * .08 : 0;
468:     }
469:     for (const [id, obj] of entities) if (!live.has(id)) { entityRoot.remove(obj); disposeTree(obj); entities.delete(id); }
470:     syncResources(frame);
471:     syncEffects(frame);
472:     let ghost = scene.getObjectByName('placement-preview');
473:     if (frame.placement) {
474:       if (!ghost) {
475:         ghost = new THREE.Mesh(new THREE.BoxGeometry(8, 4, 8), new THREE.MeshBasicMaterial({ color: '#c8f05b', wireframe: true, transparent: true, opacity: .8 }));
476:         ghost.name = 'placement-preview'; scene.add(ghost);
477:       }
478:       const pointer = frame.pointer || { x: .5, y: .5 };
479:       position(ghost, pointer.x, pointer.y, 2); ghost.visible = true;
480:     } else if (ghost) ghost.visible = false;
481:     renderer.render(scene, camera);
482:   }
